import { nextBasketResponse } from '../support/basket-response';

export class BasketPage {
  readonly rows: Locator;
  readonly totalPrice: Locator;
  readonly checkoutButton: Locator;
  readonly snackBar: Locator;
  readonly errorMessages: Locator;

  constructor(private readonly page: Page) {
    this.rows = page.locator('app-basket mat-row');
    this.totalPrice = page.locator('app-basket #price');
    this.checkoutButton = page.locator('app-basket #checkoutButton');
    this.snackBar = page.locator('.mat-mdc-snack-bar-container');
    this.errorMessages = this.snackBar.and(page.locator('.errorBar'));
  }

  /**
   * Opens the basket and waits until the table shows the products that the server sent.
   * `#price` renders with `0` before the data arrives, so it does not prove that the basket loaded.
   */
  async open(): Promise<void> {
    const serverBasket = nextBasketResponse(this.page);
    await this.page.goto('/#/basket');
    await this.waitForLoad();
    await expect(this.rows, 'The basket table shows the products of the server basket').toHaveCount(
      (await serverBasket).Products.length,
    );
  }"}
